    /// <summary>
    /// Lookup to display Tariff item stat code and description 
    /// </summary>
    /// <param name="sender">
    /// sender get the form name 
    /// </param>
    /// <param name="e">
    /// e gets the formcontrol 
    /// </param>
    [FormControlEventHandler(formControlStr(EcoResProductDetailsExtended, METInventTable_METTariffItemCodeRecid), FormControlEventType::Lookup)]
    public static void METInventTable_METTariffItemCodeRecid_OnLookup(FormControl sender, FormControlEventArgs e)
    {
        SysReferenceTableLookup tariffItemCodeLookup;
        Query query = new Query();
        QueryBuildDataSource queryBuildDataSource;
       
        tariffItemCodeLookup = SysReferenceTableLookup::newParameters(tableNum(METTariffItemCodeBase), sender);

        // Add the fields to be shown in the lookup form.
        tariffItemCodeLookup.addLookupfield(fieldNum(METTariffItemCodeBase, TariffItem));
        tariffItemCodeLookup.addLookupfield(fieldNum(METTariffItemCodeBase, StatCode));
        tariffItemCodeLookup.addLookupfield(fieldNum(METTariffItemCodeBase, Description));

        queryBuildDataSource = query.addDataSource(tableNum(METTariffItemCodeBase));
        tariffItemCodeLookup.parmQuery(query);

        // Perform the lookup.
        tariffItemCodeLookup.performFormLookup();

        FormControlCancelableSuperEventArgs cancelableArgs = e as FormControlCancelableSuperEventArgs;
        cancelableArgs.CancelSuperCall();
    }

/// <summary>
/// Updated InventTableRecId automatically so that we dont have to select the Item Id Manually.
/// </summary>
/// <param name="sender">
/// sender get the Form Data Source
/// </param>
/// <param name="e">
/// e get Form DataSourceEventArgs
/// </param>
[FormDataSourceEventHandler(formDataSourceStr(EcoResProductDetailsExtended, METInventTable), FormDataSourceEventType::ValidatedWrite),
 SuppressBPWarning("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")]
public static void METInventTable_OnValidatedWrite(FormDataSource sender, FormDataSourceEventArgs e)
{
    FormRun                 form              = sender.formRun();
    FormDataSource          inventTable_ds    = form.dataSource(formDataSourceStr(EcoResProductDetailsExtended, InventTable)) as FormDataSource;
    FormDataSource          metInventTable_ds = form.dataSource(formDataSourceStr(EcoResProductDetailsExtended, MetInventTable)) as FormDataSource;
    METInventTable          metInventTable    = metInventTable_ds.cursor();
    InventTable             inventTable       = inventTable_ds.cursor();
    
    metInventTable.ItemId = inventTable.ItemId;
    
}

    /// <summary>
    /// MPJ_21275_BackOrders
    /// Modify based on the user selected back order on item master level and it will give an info
    /// </summary>
    /// <param name="sender">form datasource</param>
    /// <param name="e">Data field</param>
    [
        FormDataFieldEventHandler(formDataFieldStr(EcoResProductDetailsExtended, METInventTable, AllowBackOrders), FormDataFieldEventType::Modified),
        SuppressBPWarningAttribute('BPParameterNotUsed', "@MET:BPParameterNotUsedMessage")
    ]
    public static void AllowBackOrders_OnModified(FormDataObject sender, FormDataFieldEventArgs e)
    {
        FormDataSource  metInventTable_ds   = sender.datasource();
        METInventTable  metInventTable      = metInventTable_ds.cursor();
        DialogButton    dialogButton;
        
        if (metInventTable.AllowBackOrders == NoYes::No)
        {
            dialogButton = Box::yesNo("@MET:METItemMasterDisableBackOrder", DialogButton::Yes);
            
            if (dialogButton == DialogButton::No)
            {
                metInventTable.AllowBackOrders = NoYes::Yes;
            }
            else
            {
                metInventTable.AllowBackOrders = NoYes::No;
            }
        }

        else if (metInventTable.AllowBackOrders == NoYes::Yes)
        {
            dialogButton = Box::yesNo("@MET:METItemMasterActivateBackOrder", DialogButton::Yes);
            
            if (dialogButton == DialogButton::No)
            {
                metInventTable.AllowBackOrders = NoYes::No;
            }
            else
            {
                metInventTable.AllowBackOrders = NoYes::Yes;
            }
        }
    }

/// <summary>
/// MPJ_26957_AllowBackOrders
/// Activate the Item header level allowback order based on cust parameter
/// </summary>
/// <param name="sender">Form Data source</param>
/// <param name="e">Form data source event</param>
[FormDataSourceEventHandler(formDataSourceStr(EcoResProductDetailsExtended, METInventTable), FormDataSourceEventType::Activated),
    SuppressBPWarningAttribute('BPParameterNotUsed', "@MET:BPParameterNotUsedMessage")]
public static void METInventTable_OnActivated(FormDataSource sender, FormDataSourceEventArgs e)
{
    FormCheckboxControl backorder       = sender.formRun().design(0).controlName(formControlStr(EcoResProductDetailsExtended, BackOrders_AllowBackOrders));

    if(CustParameters::find().METAllowBackOrders == NoYes::Yes)
    {
        backorder.enabled(true);
    }
    else
    {
        backorder.enabled(false);
    }
}
